breach.segment:
WHERE marker > 0
| EVAL failover_requests = COALESCE(failover_requests, 0)
// Breach: an auto-failover request, or an unplanned minute with less than 55 s of uptime (0-54 s; 59-61 s is
// collection jitter) followed by a full minute, i.e. the instance went down and came back.
// Ongoing outages (latest minute still short) are left to the "Instance not serving" rule.
// To alert on planned restarts too, replace "unplanned_short_minutes > 0" with "partial_uptime_minutes + zero_uptime_minutes > 0".
| WHERE failover_requests > 0
     OR (unplanned_short_minutes > 0 AND latest_uptime_s >= 55)
| EVAL event_type = CASE(failover_requests > 0, "auto failover", "restart")
| SORT database_id ASC
// Up to 1000 breaching instances per run (the ES|QL default row limit); raise it for larger fleets
| LIMIT 1000
| KEEP database_id, event_type, partial_uptime_minutes, zero_uptime_minutes, unplanned_short_minutes, latest_uptime_s, failover_requests
